from pathlib import Pathimport requestsimport pandas as pd# PathsPROJECT_ROOT = Path(__file__).resolve().parent.parentOUTPUT_DIR = PROJECT_ROOT / "data" / "processed"RAW_DIR = PROJECT_ROOT / "data" / "raw"OUTPUT_DIR.mkdir(parents=True, exist_ok=True)RAW_DIR.mkdir(parents=True, exist_ok=True)RAW_FILE = RAW_DIR / "Kp_def2024.wdc"KP_3H_FILE = (    OUTPUT_DIR /    "kp_3hour_2024-04-01_to_2024-06-30.csv")DAILY_KP_FILE = (    OUTPUT_DIR /    "kp_daily_2024-04-01_to_2024-06-30.csv")# Official GFZ definitive archiveURL = (    "https://datapub.gfz.de/download/"    "10.5880.Kp.0001/Kp_definitive/"    "Kp_def2024.wdc")def main():    print("Downloading definitive 2024 Kp data...")    response = requests.get(URL, timeout=60)    response.raise_for_status()    content = response.text    if "<html" in content.lower():        raise RuntimeError(            "GFZ returned HTML instead of WDC data."        )    RAW_FILE.write_text(content, encoding="utf-8")    print(f"Saved raw archive: {RAW_FILE}")    # WDC format:    # positions 0:2  = year (two digits)    # positions 2:4  = month    # positions 4:6  = day    # positions 12:28 = eight Kp values,    # each stored as a two-character integer    # representing Kp multiplied by 10.    rows = []    for line in content.splitlines():        if not line.strip() or line.startswith("#"):            continue        if len(line) < 28:            continue        try:            year = 2000 + int(line[0:2])            month = int(line[2:4])            day = int(line[4:6])            base_date = pd.Timestamp(                year=year,                month=month,                day=day,                tz="UTC",            )        except ValueError:            continue        if year != 2024:            continue        for i in range(8):            start = 12 + 2 * i            end = start + 2            try:                raw_kp = int(line[start:end])            except ValueError:                continue            # 99 represents missing data            if raw_kp == 99:                continue            kp_value = raw_kp / 10.0            if not 0 <= kp_value <= 9:                continue            timestamp = (                base_date                + pd.Timedelta(hours=3 * i)            )            rows.append({                "datetime": timestamp,                "Kp": kp_value,                "status": "def",            })    df = pd.DataFrame(rows)    if df.empty:        raise ValueError(            "No valid Kp values parsed. "            "Check the archive format."        )    df = df[        (df["datetime"] >= "2024-04-01")        & (df["datetime"] < "2024-07-01")    ].copy()    if df.empty:        raise ValueError(            "No Kp observations found for April-June."        )    df = df.sort_values("datetime")    df["storm"] = df["Kp"] >= 5    df.to_csv(KP_3H_FILE, index=False)    # Daily maximum Kp    df["date"] = df["datetime"].dt.floor("D")    daily = (        df.groupby("date", as_index=False)["Kp"]        .max()        .rename(columns={"Kp": "daily_max_kp"})    )    daily["storm_day"] = daily["daily_max_kp"] >= 5    daily.to_csv(DAILY_KP_FILE, index=False)    print(f"\n3-hourly records: {len(df)}")    print(f"Daily records: {len(daily)}")    print(f"\nSaved: {KP_3H_FILE}")    print(f"Saved: {DAILY_KP_FILE}")    # Verify the major May 2024 storm    may = daily[        (daily["date"] >= "2024-05-08")        & (daily["date"] <= "2024-05-15")    ]    print("\nMay 8-15 Kp measurements:")    print(may.to_string(index=False))    if len(daily) < 90:        print(            "\nWarning: fewer days than expected. "            "Check for missing archive records."        )    print("\nCIRBE Kp download complete!")if __name__ == "__main__":    main()